import bisect
def lis(nums, side):
    tails = []
    for x in nums:
        i = side(tails, x)
        if i == len(tails): tails.append(x)
        else: tails[i] = x
    return len(tails)
first = [10, 9, 2, 5, 3, 7, 101, 18]
print('on', first, ': bisect_right gives', lis(first, bisect.bisect_right), '(no duplicates, so the slip hides)')
print('on [7, 7, 7, 7]: bisect_right gives', lis([7, 7, 7, 7], bisect.bisect_right), 'but the strict answer is 1')
print('landing AFTER an equal tail treats 7 -> 7 as an increase')
